%[text] 发现2:Transfer 过程是layer 2为模版的，L2编码了早期的记忆，晚期的动作目的，并在迁移过程中共用了L2，而L5参与了行为
%[text:tableOfContents]{"heading":"目录"}
%%
ALB=TransferLearning.AudioLightBaseline;
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
%%
%[text] # 学习早期
%[text] 2层功能：记录刺激
%[text] 1. 时间提前
%[text] 2. 活动低
%[text] 3. 对cue不响应 \
%[text] L5无时间提前
%[text] L2早于L5
%[text] ## A
%[text] 群体活动总览：1s内达到基线3倍标准差的所有细胞
EnsembleA=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2A'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median));
[~,Index]=ismember(EnsembleA.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
%%
EnsembleLogical=max(EnsembleA.NTATS.AudioWater(:,25:32),[],2)>std(EnsembleA.NTATS.AudioWater(:,1:24),[],2)*3;
Layer2Logical=ZLayer=="MOp2/3";
Layer5Logical=ZLayer=="MOp5";
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
%%
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["AudioOnly","WaterOnly","AudioWater"];
HLData=table;
HLData.(LayerTitles(1))=permute(EnsembleA.NTATS{Ensemble2,:,Phases},[3,1,2]);
HLData.(LayerTitles(2))=permute(EnsembleA.NTATS{Ensemble5,:,Phases},[3,1,2]);
HLData.Properties.RowNames=Phases';
%%
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=":k";
XLine.Time=seconds(0);
Fig=figure;
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(HLData(:,LayerTitles),seconds([-3,3]),XLine=XLine);
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1)));
ylabel(Axes(3,1),'z-score ± SEM');
ColorBar.Label.String='z-score';
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
title(Layout,'Ensemble Naive');
print(Fig,TransferLearning.ProjectPath('Fig2A.svg'),'-dsvg');
%%
%[text] ## B
Fig=figure; %[output:1b59fb1f]
Layout=tiledlayout(2,2,TileSpacing='tight',Padding='compact');%Padding如果用tight，右边坐标轴会出界 %[output:1b59fb1f]
%[text] 2层时间提前：AudioWater相比于AudioOnly
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B12'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:7ab46aec]
EnsembleB12=GroupNtats(max(GroupNtats.NTATS.AudioWater(:,25:32),[],2)>std(GroupNtats.NTATS.AudioWater(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleB12.CellUID,ALB.Cells.CellUID);
EnsembleB12.Mouse=ALB.Cells.Mouse(Index);
EnsembleB12.Signal=EnsembleB12.NTATS{:,25:end,["AudioOnly","AudioWater"]};
MouseRisingTime=groupsummary(EnsembleB12,'Mouse',@(Signal)mean(Signal,1),'Signal');
[~,RisingTime]=max(diff(MouseRisingTime.fun1_Signal,1,2),[],2);
nexttile; %[output:1b59fb1f]
UniExp.BarScatterCompare(array2table(permute(RisingTime*milliseconds(125),[1,3,2]),'VariableNames',["🔊","🔊💧"]),false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:1b59fb1f]
ylabel('Rising time (s)'); %[output:1b59fb1f]
title('Layer 2'); %[output:1b59fb1f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:1b59fb1f]
%[text] 2层活动强度：AudioWater比AudioOnly强
Response=max(EnsembleB12.NTATS(:,25:32,:),[],2);
nexttile; %[output:1b59fb1f]
UniExp.BarScatterCompare(table(Response.AudioOnly,Response.AudioWater,'VariableNames',["🔊","🔊💧"]),false,table(["🔊","🔊💧"],'VariableNames',"GroupPair")); %[output:1b59fb1f]
ylabel('Max z-score in 1s'); %[output:1b59fb1f]
title('Layer 2'); %[output:1b59fb1f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:1b59fb1f]
%[text] 5层：AudioWater与WaterOnly时间比较
GroupNtats=UniExp.NtatsCellStrip(ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B3'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:0914e2f6]
EnsembleB3=GroupNtats(max(GroupNtats.NTATS.AudioWater(:,25:32),[],2)>std(GroupNtats.NTATS.AudioWater(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleB3.CellUID,ALB.Cells.CellUID);
EnsembleB3.Mouse=ALB.Cells.Mouse(Index);
EnsembleB3.Signal=EnsembleB3.NTATS{:,25:end,["WaterOnly","AudioWater"]};
MouseRisingTime=groupsummary(EnsembleB3,'Mouse',@(Signal)mean(Signal,1),'Signal');
[~,RisingTime]=max(diff(MouseRisingTime.fun1_Signal,1,2),[],2);
nexttile; %[output:1b59fb1f]
UniExp.BarScatterCompare(array2table(permute(RisingTime*milliseconds(125),[1,3,2]),'VariableNames',["💧","🔊💧"]),false,table(["💧","🔊💧"],'VariableNames',"GroupPair")); %[output:1b59fb1f]
ylabel('Rising time (s)'); %[output:1b59fb1f]
title('Layer 5'); %[output:1b59fb1f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:1b59fb1f]
%[text] L2早于L5
EnsembleB4=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2B4'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:491beb27]
RisingTime=struct;
for L=["Layer2","Layer5"]
	NTATS=EnsembleB4.(L);
	NTATS=NTATS(max(NTATS.NTATS(:,25:32),[],2)>std(NTATS.NTATS(:,1:24),[],2)*3,:);
	[~,Index]=ismember(NTATS.CellUID,ALB.Cells.CellUID);
	NTATS.Mouse=ALB.Cells.Mouse(Index);
	NTATS.Signal=NTATS.NTATS(:,25:end);
	MouseRisingTime=groupsummary(NTATS,'Mouse',@(Signal)mean(Signal,1),'Signal');
	[~,RT]=max(diff(MouseRisingTime.fun1_Signal,1,2),[],2);
	RisingTime.(L)=RT*milliseconds(125);
end
nexttile; %[output:1b59fb1f]
UniExp.BarScatterCompare(RisingTime,false,table(["Layer2","Layer5"],'VariableNames',"GroupPair")); %[output:1b59fb1f]
ylabel('Rising time (s)'); %[output:1b59fb1f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:1b59fb1f]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:1b59fb1f]
Layout.Padding="compact";
print(Fig,TransferLearning.ProjectPath('Fig2B.svg'),'-dsvg'); %[output:1b59fb1f]
%%
%[text] # 学习后和迁移过程
%[text] L2功能：指导L5行动
%[text] 1. 时间提前
%[text] 2. 活动高
%[text] 3. 形成correlation ensemble？ \
%[text] L5
%[text] 1. 时间提前
%[text] 2. 响应增强 \
%[text] L2与L5 同时?
%[text] 2层：指导L5 transfer
%[text] 1. 时间提前
%[text] 2. 活动低 \
%[text] （反应时间有变化么？）
%[text] （分trial 后，反应概率下降：显示cue的变化）
%[text] 5层
%[text] 1. 时间提前
%[text] 2. 响应弱 \
%[text] 相同Ensemble？
%[text] L2与L5同时？
%[text] ## C
EnsembleCD=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2CD'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
EnsembleC=UniExp.NtatsCellStrip(EnsembleCD);
%%
[~,Index]=ismember(EnsembleC.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
Layer5Logical=ZLayer=="MOp5";
Layer2Logical=~Layer5Logical;
EnsembleLogical=max(EnsembleC.NTATS.Learned(:,25:32),[],2)>std(EnsembleC.NTATS.Learned(:,1:24),[],2)*3;
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["Naive","Learned","Transfer"];
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=[":k";"-k"];
XLine.Time=seconds([0;1]);
Fig=figure;
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(table(permute(EnsembleC.NTATS{Ensemble2,:,Phases},[3,1,2]),permute(EnsembleC.NTATS{Ensemble5,:,Phases},[3,1,2]),'VariableNames',LayerTitles,'RowNames',Phases),seconds([-3,3]),XLine=XLine);
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1)));
ylabel(Axes(3,1),'z-score ± SEM');
ColorBar.Label.String='z-score';
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
title(Layout,'Ensemble Learned')
print(Fig,TransferLearning.ProjectPath('Fig2C.svg'),'-dsvg');
%%
%[text] ## D
%[text] 时间统计
Fig=figure;
Layout=tiledlayout(2,3,TileSpacing='tight',Padding='compact');
EnsembleCD.Naive.Phase(:)="Naive";
EnsembleCD.Learned.Phase(:)="Learned";
EnsembleD1=[EnsembleCD.Naive;EnsembleCD.Learned];
EnsembleD1=EnsembleD1(max(EnsembleD1.NTATS(:,25:32),[],2)>std(EnsembleD1.NTATS(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleD1.CellUID,ALB.Cells.CellUID);
EnsembleD1.ZLayer=ALB.Cells.ZLayer(Index);
[~,RisingTime]=max(diff(EnsembleD1.NTATS(:,25:end),1,2),[],2);
EnsembleD1.RisingTime=RisingTime*milliseconds(125);
TimeComparison=UniExp.TabularAnovaN(EnsembleD1.RisingTime,EnsembleD1(:,["Phase","ZLayer"]),Comparison=table(["Naive","Learned";"Naive","Learned";"Learned","Learned"],["MOp2/3","MOp2/3";"MOp5","MOp5";"MOp2/3","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(EnsembleD1,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
nexttile;
Bars=bar(reshape(BarData.mean_RisingTime,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/5;
PY=max(reshape(BarData.mean_RisingTime+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
PY=PY(1,:)+LevelStep;
text(1:2,PY,"p="+MATLAB.SignificantFixedpoint(TimeComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
PY=max(PY);
line(PX(1,:),[PY,PY],Color='k');
text(mean(PX(1,:)),PY+LevelStep,"p="+MATLAB.SignificantFixedpoint(TimeComparison.PValue(3),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Rising time');
%[text] 峰值统计
EnsembleD1.Response=max(EnsembleD1.NTATS(:,25:32),[],2);
ResponseComparison=UniExp.TabularAnovaN(EnsembleD1.Response,EnsembleD1(:,["Phase","ZLayer"]),Comparison=table(["Naive","Learned";"Naive","Learned"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(EnsembleD1,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile;
Bars=bar(reshape(BarData.mean_Response,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/5;
PY=max(reshape(BarData.mean_Response+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
text(1:2,PY(1,:)+LevelStep,"p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Max z-score in 1s');
L=legend(Bars,"Ensemble "+unique(BarData.Phase));
L.Layout.Tile=3;
%[text] LT对比
EnsembleD2=UniExp.NtatsCellStrip(rmfield(EnsembleCD,'Naive'));
EnsembleD2=EnsembleD2(max(EnsembleD2.NTATS.Learned(:,25:32),[],2)>std(EnsembleD2.NTATS.Learned(:,1:24),[],2)*3,:);
[~,Index]=ismember(EnsembleD2.CellUID,ALB.Cells.CellUID);
AnovaTable=table;
AnovaTable.NTATS=[EnsembleD2.NTATS.Learned;EnsembleD2.NTATS.Transfer];
NumCells=height(EnsembleD2);
AnovaTable.Phase(1:NumCells)="Learned";
AnovaTable.Phase(NumCells+1:end)="Transfer";
AnovaTable.ZLayer=ALB.Cells.ZLayer([Index;Index]);
[~,RisingTime]=max(diff(AnovaTable.NTATS(:,25:end),1,2),[],2);
AnovaTable.RisingTime=RisingTime*milliseconds(125);
AnovaTable.Response=max(AnovaTable.NTATS(:,25:32),[],2);
TimeComparison=UniExp.TabularAnovaN(AnovaTable.RisingTime,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Learned","Transfer";"Learned","Transfer";"Transfer","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5";"MOp2/3","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
nexttile(4);
Bars=bar(reshape(BarData.mean_RisingTime,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/5;
PY=max(reshape(BarData.mean_RisingTime+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
PY=PY(1,:)+LevelStep;
text(1:2,PY,"*",HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
PY=max(PY);
line(PX(1,:),[PY,PY],Color='k');
text(mean(PX(1,:)),PY+LevelStep,"p="+MATLAB.SignificantFixedpoint(TimeComparison.PValue(3),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Rising time');
%[text] 峰值统计
ResponseComparison=UniExp.TabularAnovaN(AnovaTable.Response,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Learned","Transfer";"Learned","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile;
Bars=bar(reshape(BarData.mean_Response,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/5;
PY=max(reshape(BarData.mean_Response+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
text(1:2,PY(1,:)+LevelStep,"p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Max z-score in 1s');
L=legend(Bars,"Phase "+unique(BarData.Phase));
L.Layout.Tile=6;
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
print(Fig,TransferLearning.ProjectPath('Fig2D.svg'),'-dsvg');
%%
%[text] # 后期学习
%[text] 2层：分离新任务
%[text] 1. 时间提前
%[text] 2. 活动高 \
%[text] （形成 新correlation ensemble？）
%[text] 5层
%[text] 1. 时间提前
%[text] 2. 响应增强 \
%[text] 新Ensemble？
%[text] L2与L5同时？
%[text] ## E
EnsembleEF=ALB.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig2EF'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median); %[output:4645ea8c]
EnsembleE=UniExp.NtatsCellStrip(EnsembleEF);
[~,Index]=ismember(EnsembleE.CellUID,ALB.Cells.CellUID);
ZLayer=ALB.Cells.ZLayer(Index);
Layer5Logical=ZLayer=="MOp5";
Layer2Logical=~Layer5Logical;
EnsembleLogical=max(EnsembleE.NTATS.Final(:,25:32),[],2)>std(EnsembleE.NTATS.Final(:,1:24),[],2)*3;
Ensemble2=Layer2Logical&EnsembleLogical;
Ensemble5=Layer5Logical&EnsembleLogical;
LayerTitles=["Layer2 "+MATLAB.SignificantFixedpoint(sum(Ensemble2)/sum(Layer2Logical)*100,2)+"%","Layer5 "+MATLAB.SignificantFixedpoint(sum(Ensemble5)/sum(Layer5Logical)*100,2)+"%"];
Phases=["Learned","Transfer","Final"];
XLine=timetable;
%timetable的局限性，必须先制定列后指定时间
XLine.LineStyle=[":k";"-k"];
XLine.Time=seconds([0;1]);
Fig=figure; %[output:5e48b03c]
[Layout,Axes,Lines,ColorBar]=UniExp.HeatmapLine(table(permute(EnsembleE.NTATS{Ensemble2,:,Phases},[3,1,2]),permute(EnsembleE.NTATS{Ensemble5,:,Phases},[3,1,2]),'VariableNames',LayerTitles,'RowNames',Phases),seconds([-3,3]),XLine=XLine); %[output:5e48b03c]
legend(Lines(:,1),["Layer 2","Layer 5"],Location=MATLAB.Graphics.OptimizedLegendLocation(Lines(:,1))); %[output:5e48b03c]
ylabel(Axes(3,1),'z-score ± SEM'); %[output:5e48b03c]
ColorBar.Label.String='z-score'; %[output:5e48b03c]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:5e48b03c]
title(Layout,'Ensemble Final') %[output:5e48b03c]
print(Fig,TransferLearning.ProjectPath('Fig2E.svg'),'-dsvg'); %[output:5e48b03c]
%%
%[text] ## F
Fig=figure; %[output:5b410a5f]
Layout=tiledlayout(1,2,TileSpacing='tight',Padding='compact'); %[output:5b410a5f]
EnsembleFLT=UniExp.NtatsCellStrip(rmfield(EnsembleEF,'Final'));
EnsembleFLT=EnsembleFLT(max(EnsembleFLT.NTATS.Learned(:,25:32),[],2)>std(EnsembleFLT.NTATS.Learned(:,1:24),[],2)*3,:);
EnsembleFLT.NTATS=EnsembleFLT.NTATS.Transfer;
EnsembleFLT.Phase(:)="Transfer";
EnsembleFLT.Response=max(EnsembleFLT.NTATS(:,25:32),[],2);
EnsembleFF=EnsembleEF.Final;
EnsembleFF.Response=max(EnsembleFF.NTATS(:,25:32),[],2);
EnsembleFF=EnsembleFF(EnsembleFF.Response>std(EnsembleFF.NTATS(:,1:24),[],2)*3,:);
EnsembleFF.Phase(:)="Final";
EnsembleF=[EnsembleFLT;EnsembleFF];
[~,RisingTime]=max(diff(EnsembleF.NTATS(:,25:end),1,2),[],2);
EnsembleF.RisingTime=RisingTime*milliseconds(125);
[~,Index]=ismember(EnsembleF.CellUID,ALB.Cells.CellUID);
EnsembleF.ZLayer=ALB.Cells.ZLayer(Index);
TimeComparison=UniExp.TabularAnovaN(EnsembleF.RisingTime,EnsembleF(:,["Phase","ZLayer"]),Comparison=table(["Transfer","Final";"Transfer","Final"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(EnsembleF,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
nexttile; %[output:5b410a5f]
Bars=bar(reshape(BarData.mean_RisingTime,2,2)); %[output:5b410a5f]
hold on; %[output:5b410a5f]
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:5b410a5f]
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/10;
PY=max(reshape(BarData.mean_RisingTime+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k'); %[output:5b410a5f]
PY=PY(1,:)+LevelStep;
text(1:2,PY,"*",HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true); %[output:5b410a5f]
colororder([1,0,1;0,0.5,0]); %[output:5b410a5f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:5b410a5f]
xticklabels(["Layer 2","Layer 5"]); %[output:5b410a5f]
ylabel('Rising time'); %[output:5b410a5f]
%[text] 峰值统计
ResponseComparison=UniExp.TabularAnovaN(EnsembleF.Response,EnsembleF(:,["Phase","ZLayer"]),Comparison=table(["Transfer","Final";"Transfer","Final"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(EnsembleF,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile; %[output:5b410a5f]
Bars=bar(reshape(BarData.mean_Response,2,2)); %[output:5b410a5f]
hold on; %[output:5b410a5f]
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none'); %[output:5b410a5f]
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/10;
PY=max(reshape(BarData.mean_Response+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k'); %[output:5b410a5f]
text(1:2,PY(1,:)+LevelStep,"*",HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true); %[output:5b410a5f]
colororder([1,0,1;0,0.5,0]); %[output:5b410a5f]
YLim=ylim;
ylim([0,YLim(2)]); %[output:5b410a5f]
xticklabels(["Layer 2","Layer 5"]); %[output:5b410a5f]
ylabel('Max z-score in 1s'); %[output:5b410a5f]
L=legend(Bars,unique(BarData.Phase)); %[output:5b410a5f]
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow); %[output:5b410a5f]
print(Fig,TransferLearning.ProjectPath('Fig2F.svg'),'-dsvg'); %[output:5b410a5f]
%%
%[text] # （备用）
%[text] 
%%
%[text] 与光水Naive比较
EnsembleF2=LAB.QueryNTATS(struct(Stimulus="LightWater",Phase="Naive"),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median);
%%
EnsembleF2=EnsembleF2(max(EnsembleF2.NTATS{:,25:32},[],2)>std(EnsembleF2.NTATS{:,1:24},[],2)*3,:);
[~,Index]=ismember(EnsembleF2.CellUID,LAB.Cells.CellUID);
EnsembleF2.ZLayer=LAB.Cells.ZLayer(Index);
EnsembleF2.Phase(:)="Naive";
%%
[~,RisingTime]=max(diff(EnsembleF2.NTATS{:,25:end},1,2),[],2);
EnsembleF2.RisingTime=RisingTime*milliseconds(125);
EnsembleF2.Response=max(EnsembleF2.NTATS{:,25:32},[],2);
AnovaTable(AnovaTable.Phase=="Learned",:)=[];
%%
EnsembleF2.NTATS=EnsembleF2.NTATS.Data;
%%
AnovaTable=[AnovaTable;EnsembleF2(:,["NTATS","Phase","ZLayer","RisingTime","Response"])];
%%
TimeComparison=UniExp.TabularAnovaN(AnovaTable.RisingTime,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Naive","Transfer";"Naive","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
%%
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"RisingTime");
BarData.SEM=BarData.std_RisingTime./sqrt(BarData.GroupCount);
%%
nexttile;
Bars=bar(reshape(BarData.mean_RisingTime,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/6;
PY=max(reshape(BarData.mean_RisingTime+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
PY=PY(1,:)+LevelStep;
text(1:2,PY,"p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Rising time');
legend(Bars,unique(BarData.Phase),Location='southeast');
%%
%[text] 峰值统计
ResponseComparison=UniExp.TabularAnovaN(AnovaTable.Response,AnovaTable(:,["Phase","ZLayer"]),Comparison=table(["Naive","Transfer";"Naive","Transfer"],["MOp2/3","MOp2/3";"MOp5","MOp5"],'VariableNames',["Phase","ZLayer"]),Model=2,Display=false);
BarData=groupsummary(AnovaTable,["Phase","ZLayer"],["mean","std"],"Response");
BarData.SEM=BarData.std_Response./sqrt(BarData.GroupCount);
nexttile;
Bars=bar(reshape(BarData.mean_Response,2,2));
hold on;
errorbar([Bars.XEndPoints],[Bars.YEndPoints],[],BarData.SEM,'k',LineWidth=2,LineStyle='none');
PX=vertcat(Bars.XEndPoints);
YLim=ylim;
LevelStep=YLim(2)/6;
PY=max(reshape(BarData.mean_Response+BarData.SEM,2,2),[],2).'+LevelStep;
PY=[PY;PY];
line(PX,PY,Color='k');
text(1:2,PY(1,:)+LevelStep,"p="+MATLAB.SignificantFixedpoint(ResponseComparison.PValue(1:2),2),HorizontalAlignment='center',VerticalAlignment='top',AffectAutoLimits=true);
colororder([1,0,1;0,0.5,0]);
YLim=ylim;
ylim([0,YLim(2)]);
xticklabels(["Layer 2","Layer 5"]);
ylabel('Max z-score in 1s');
%%


